mapper.delete:
delete from t_article_reply_like
where replyId = #{replyId,jdbcType=BIGINT}
  and userId = #{userId,jdbcType=BIGINT}

mapper.select:
select count(*)
from t_article_reply_like
where replyId = #{replyId,jdbcType=BIGINT}
  and userId = #{userId,jdbcType=BIGINT}

select rl.replyId
from t_article_reply_like rl
inner join t_article_reply ar on rl.replyId = ar.id
where ar.articleId = #{articleId,jdbcType=BIGINT}
  and rl.userId = #{userId,jdbcType=BIGINT}
